CREATE TABLE IF NOT EXISTS users (id VARCHAR(64) PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,nickname VARCHAR(100),role VARCHAR(32) NOT NULL DEFAULT 'user',status VARCHAR(32) NOT NULL DEFAULT 'active',credits INTEGER NOT NULL DEFAULT 20,ui_language VARCHAR(16) NOT NULL DEFAULT 'zh-CN',theme VARCHAR(16) NOT NULL DEFAULT 'system',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS product_projects (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL REFERENCES users(id),brand VARCHAR(120),product_name VARCHAR(255) NOT NULL,country VARCHAR(16) NOT NULL DEFAULT 'US',language VARCHAR(16) NOT NULL DEFAULT 'en-US',status VARCHAR(64) NOT NULL DEFAULT 'draft',original_info JSONB NOT NULL DEFAULT '{}'::jsonb,generated_copy JSONB NOT NULL DEFAULT '{}'::jsonb,confirmed_facts JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS image_tasks (id VARCHAR(64) PRIMARY KEY,project_id VARCHAR(64) NOT NULL REFERENCES product_projects(id),user_id VARCHAR(64) NOT NULL REFERENCES users(id),image_type VARCHAR(64) NOT NULL,status VARCHAR(64) NOT NULL DEFAULT 'queued',prompt_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,result_url TEXT,credits_cost INTEGER NOT NULL DEFAULT 0,actual_cost NUMERIC(12,6),provider VARCHAR(64),model VARCHAR(128),safe_error TEXT,raw_error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS credit_ledger (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL REFERENCES users(id),change_amount INTEGER NOT NULL,balance_after INTEGER NOT NULL,biz_type VARCHAR(64) NOT NULL,biz_id VARCHAR(64),remark VARCHAR(255),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS prompt_templates (id VARCHAR(64) PRIMARY KEY,name VARCHAR(120) NOT NULL,scene VARCHAR(64) NOT NULL,version INTEGER NOT NULL DEFAULT 1,content TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS system_settings (id VARCHAR(64) PRIMARY KEY,setting_key VARCHAR(120) NOT NULL UNIQUE,setting_value JSONB NOT NULL DEFAULT '{}'::jsonb,description VARCHAR(255),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted SMALLINT NOT NULL DEFAULT 0);
